DO $$
DECLARE
    -- Simulate your dictionary payload
    payload JSON := $payload${{ JSON.stringify($json) }}$payload$;

    target_filename TEXT := payload->>'fileName';
    meta_key TEXT;
    meta_value TEXT;
    col_exists BOOLEAN;

    dynamic_ddl TEXT;
    dynamic_update TEXT;
    set_clauses TEXT[] := ARRAY[]::TEXT[];
BEGIN
    -- STEP 1: Ensure all metadata columns exist
    FOR meta_key IN SELECT json_object_keys(payload->'metadata')
    LOOP
        SELECT EXISTS (
            SELECT 1 
            FROM information_schema.columns 
            WHERE table_schema = 'public' 
              AND table_name = 'documents' 
              AND column_name = meta_key
        ) INTO col_exists;

        IF NOT col_exists THEN
            -- Add missing column (defaulting to TEXT so it catches all data types safely)
            dynamic_ddl := format('ALTER TABLE documents ADD COLUMN %I TEXT;', meta_key);
            EXECUTE dynamic_ddl;
            RAISE NOTICE 'Added new column: %', meta_key;
        END IF;
    END LOOP;

    -- STEP 2: Build the dynamic UPDATE statement
    -- Loop through both keys and values using json_each_text
    FOR meta_key, meta_value IN SELECT "key", "value" FROM json_each_text(payload->'metadata')
    LOOP
        -- Build the 'column_name = value' fragments
        -- %I safely quotes the column name, %L safely quotes the literal value
        set_clauses := array_append(set_clauses, format('%I = %L', meta_key, meta_value));
    END LOOP;

    -- If there is actually metadata to update, execute it
    IF array_length(set_clauses, 1) > 0 THEN
        dynamic_update := format(
            'UPDATE documents SET %s WHERE %I = %L;', 
            array_to_string(set_clauses, ', '),  -- Joins the SET clauses with commas
            'doc_name',                          -- Your target column
            target_filename                      -- The file name value
        );

        RAISE NOTICE 'Executing: %', dynamic_update;
        EXECUTE dynamic_update;
    END IF;

END $$;

