findings = output_payload.get("findings", [])


existing_row = _('Get a row1').last().to_py().get("json", {})
category_name = existing_row.get("category_name", "Unknown")
existing_elements_col = existing_row.get("elements", {})

# 3. Sanitization Mapping
db_keys = {
    "property": "properties",
    "behavioral_pattern": "behavioral_patterns",
    "determining_condition": "determining_conditions",
    "consequence": "consequences_or_strategies"
}

# Ensure tracked_elements starts with the existing data or empty lists
tracked_elements = {
    "properties": list(existing_elements_col.get("properties", [])),
    "behavioral_patterns": list(existing_elements_col.get("behavioral_patterns", [])),
    "determining_conditions": list(existing_elements_col.get("determining_conditions", [])),
    "consequences_or_strategies": list(existing_elements_col.get("consequences_or_strategies", []))
}

new_batch_docs = []

# 4. Process findings
for finding in findings:
    el_type = finding.get("element_type")
    action = finding.get("action")
    docs = finding.get("source_documents", [])

    # Map element type to the correct key in tracked_elements
    mapped_key = db_keys.get(el_type)
    if not mapped_key or not action:
        continue

    # Track unique source documents for the batch
    for doc in docs:
        if doc not in new_batch_docs:
            new_batch_docs.append(doc)

    target_list = tracked_elements[mapped_key]

    if action == "new":
        target_list.append({
            "description": finding.get("description", "").strip(),
            "source_documents": docs
        })

    elif action in ["confirmed", "updated"]:
        matched_text = (finding.get("matched_existing_element") or "").strip().lower()
        found_match = False

        for item in target_list:
            existing_desc = (item.get("description") or "").strip().lower()

            # Match Logic: Direct match or substring overlap
            if matched_text and (matched_text in existing_desc or existing_desc in matched_text):
                found_match = True

                # Update description if it's an "updated" action
                if action == "updated" and finding.get("description"):
                    item["description"] = finding.get("description", "").strip()

                # Merge docs (list(set()) ensures uniqueness)
                existing_docs = item.get("source_documents", [])
                item["source_documents"] = list(set(existing_docs) | set(docs))
                break

        # Fallback: if 'confirmed' but no match found, treat as new to prevent data loss
        if not found_match:
            target_list.append({
                "description": (finding.get("description") or matched_text).strip(),
                "source_documents": docs
            })

# 5. Final Payload
return {
    "json": {
        "category_name": category_name,
        "new_elements_found": new_elements_found,
        "final_elements": tracked_elements, 
        "new_batch_docs": new_batch_docs,
        "cross_case_synthesis_log": output_payload.get("cross_case_synthesis_log", "")
